/* Total tab: read-only UI and exports, independent from posting competence. */
(() => {
 'use strict';
 const p=ControleGastos.prototype,Q=TotalQuery,$=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const origins={expenses:'Despesa mensal',creditCard:'Cartão de crédito',dailyExpenses:'Gasto diário'};
 const note='Sobra tradicional = salário próprio + transferências − despesas mensais − cartão nas categorias 50/30/20. Gastos diários não são descontados. Média: todos os meses do intervalo, inclusive meses ausentes com zero.';
 const download=(body,type,name)=>{const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
 const table=(headers,rows)=>`<div class="total-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 p.totalProjection=function(){return Q.project(this.data,this.totalPeriod||{start:`${this.currentYear}-01`,end:`${this.currentYear}-12`});};
 p.initializePeriodFilter=function(){
  this.totalPeriod ||= {start:`${this.currentYear}-01`,end:`${this.currentYear}-12`};
  const host=document.querySelector('#annual-summary .period-filter');if(host&&!$('total-start')){
   host.innerHTML='<h3>Consultar período</h3><div class="filter-controls"><label>De <input id="total-start" type="month" required></label><label>Até <input id="total-end" type="month" required></label><button id="total-apply" class="btn btn-primary">Aplicar</button></div><div class="total-shortcuts">'+[['3','Últimos 3 meses'],['6','Últimos 6 meses'],['12','Últimos 12 meses'],['year','Ano atual'],['history','Histórico completo']].map(([k,l])=>`<button type="button" class="btn" data-period="${k}">${l}</button>`).join('')+'</div><p id="period-display"></p><p id="total-period-error" role="alert"></p><small>Consulta independente da competência de cadastro. Limites inclusivos.</small>';
   $('total-apply').onclick=()=>this.updatePeriodFilter();host.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{this.totalPeriod=Q.quick(this.data,b.dataset.period);this.renderAnnualSummary();});
   const panel=document.createElement('div');panel.id='total-insights';host.after(panel);
   document.querySelectorAll('#annual-summary h3,#annual-summary .label').forEach(e=>{for(const node of e.childNodes)if(node.nodeType===3)node.textContent=node.textContent.replaceAll('(Anual)','(período)').replaceAll('(Ano)','(período)');});
  }
  if($('total-start')){$('total-start').value=this.totalPeriod.start;$('total-end').value=this.totalPeriod.end;}
 };
 p.updatePeriodFilter=function(){const next={start:$('total-start').value,end:$('total-end').value};try{Q.range(next.start,next.end);}catch{$('total-period-error').textContent='Informe um período válido; o início não pode ser posterior ao fim.';return false;}this.totalPeriod=next;this.renderAnnualSummary();return true;};
 p.resetPeriodFilter=function(){this.totalPeriod=Q.quick(this.data,'year');this.renderAnnualSummary();};
 p.updatePeriodDisplay=function(){if($('period-display'))$('period-display').textContent=this.totalProjection().label;};
 p.renderAnnualIncome=function(){const m=this.totalProjection();for(const [id,v]of Object.entries({'annual-my-salary':m.my,'annual-her-salary':m.her,'annual-transferred':m.transferred,'annual-available':m.managed}))if($(id))$(id).textContent=money(v);};
 function list(app,origin,id){const rows=app.totalProjection().rows.filter(r=>r.origin===origin);$(id).innerHTML=table(['Descrição','Competência','Valor'],rows.map(r=>[r.description,r.exportMonth,money(r.value)]));}
 p.renderAnnualCredit=function(){list(this,'creditCard','annual-credit-list');};p.renderAnnualExpenses=function(){list(this,'expenses','annual-expenses-list');};
 p.updateAnnualHeaderStats=function(){const m=this.totalProjection();if($('month-expenses-total'))$('month-expenses-total').textContent=money(m.traditional);if($('month-liquid-surplus')){$('month-liquid-surplus').textContent=money(m.surplus);$('month-liquid-surplus').className='stat-value '+(m.surplus<0?'surplus-negative':'surplus-positive');}};
 const analysis=p.updateAnalysis;
 p.updateAnalysis=function(){if(this.currentMonth!=='total')return analysis.apply(this,arguments);const m=this.totalProjection();clearTimeout(this.analysisChartTimeout);clearTimeout(this.analysisChartRetryTimeout);for(const c of ['essential','desire','investment']){const ideal=m.ideal[c],real=m.real[c],diff=ideal-real;$(c+'-ideal').textContent=money(ideal);$(c+'-real').textContent=money(real);$(c+'-difference').textContent=(c==='investment'?(diff>=0?'Falta: ':'Acima da meta: '):(diff>=0?'Sobra: ':'Excedeu: '))+money(Math.abs(diff));this.updateBudgetProgress(c,real,ideal);this.updateBudgetStatus(c,real,ideal);}this.updateBudgetChart(m.ideal.essential,m.ideal.desire,m.ideal.investment,m.real.essential,m.real.desire,m.real.investment);};
 p.renderAnnualSummary=function(){
  this.initializePeriodFilter();const m=this.totalProjection();document.querySelector('#annual-summary h2').textContent='Total · '+m.label;this.updatePeriodDisplay();$('total-period-error').textContent='';
  for(const c of this.totalCharts||[])c.destroy();this.totalCharts=[];
  $('total-insights').innerHTML=`<div class="total-cards"><article><span>Total geral sem espelhos</span><strong id="total-general">${money(m.general)}</strong><small>Mensais + cartão + diários</small></article><article><span>Gastos tradicionais</span><strong>${money(m.traditional)}</strong><small>Mesma fórmula do cabeçalho</small></article><article><span>Sobra tradicional</span><strong id="total-surplus">${money(m.surplus)}</strong></article><article><span>Média mensal da sobra</span><strong id="total-average">${money(m.average)}</strong><small>${m.count} meses; ${m.present} com estrutura salva</small></article></div><p>${note}</p><p>${m.mirrors} espelho(s) explícito(s) de cartão desconsiderado(s) apenas no total geral, gráficos de gastos e ranking. Descrições e valores iguais, sem vínculo comprovado, permanecem separados.</p>${m.warnings.length?'<p role="alert">Há identificadores ausentes ou repetidos. Nenhum registro ambíguo foi descartado.</p>':''}<h3>Gastos por mês</h3><div class="total-chart"><canvas id="total-monthly-chart" aria-label="Comparação mensal de gastos" role="img"></canvas></div><h3>Evolução da sobra financeira</h3><div class="total-chart"><canvas id="total-surplus-chart" aria-label="Sobra e média mensal" role="img"></canvas></div><details><summary>Ver valores dos gráficos</summary>${table(['Mês','Mensais','Cartão','Diários','Total geral','Sobra'],m.monthly.map(r=>[r.label,...['expenses','creditCard','dailyExpenses','general','surplus'].map(k=>money(r[k]))]))}</details><h3>10 maiores gastos</h3><div id="total-ranking">${table(['Descrição','Valor','Mês/ano','Origem'],m.ranking.map(r=>[r.description,money(r.value),r.exportMonth,origins[r.origin]]))}</div><div class="total-shortcuts"><button class="btn" id="total-excel">Excel</button><button class="btn" id="total-pdf">PDF</button><button class="btn" id="total-html">HTML</button></div>`;
  if(globalThis.Chart){const options={animation:false,responsive:true,maintainAspectRatio:false,plugins:{tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${money(c.parsed.y)}`}}},scales:{y:{ticks:{callback:v=>money(v)}}}};this.totalCharts.push(new Chart($('total-monthly-chart'),{type:'bar',data:{labels:m.monthly.map(r=>r.label),datasets:[['expenses','Mensais','#7c3cff'],['creditCard','Cartão','#2684ff'],['dailyExpenses','Diários','#f6ae2d']].map(([k,label,backgroundColor])=>({label,backgroundColor,data:m.monthly.map(r=>r[k])}))},options}));this.totalCharts.push(new Chart($('total-surplus-chart'),{type:'line',data:{labels:m.monthly.map(r=>r.label),datasets:[{label:'Sobra tradicional',data:m.monthly.map(r=>r.surplus),borderColor:'#31b789',tension:.15},{label:'Média do intervalo',data:m.monthly.map(()=>m.average),borderColor:'#a68bdf',borderDash:[5,5],pointRadius:0}]},options}));}
  $('total-excel').onclick=()=>this.exportarExcel();$('total-pdf').onclick=()=>this.exportarPDF();$('total-html').onclick=()=>this.exportTotalHTML();this.renderAnnualIncome();this.renderAnnualCredit();this.renderAnnualExpenses();this.updateAnnualHeaderStats();if(this.currentMonth==='total')this.updateAnalysis();
 };
 p.totalReportTables=function(){const m=this.totalProjection();return {model:m,tables:[['Resumo',[['Indicador','Valor'],['Período',m.label],['Total geral sem espelhos',m.general],['Gastos tradicionais',m.traditional],['Total sob gestão',m.managed],['Sobra tradicional',m.surplus],['Média mensal da sobra',m.average],['Meses no denominador',m.count],['Critério',note]]],['50-30-20',[['Categoria','Ideal','Real'],...['essential','desire','investment'].map((c,i)=>[['Essencial','Desejo','Investimento'][i],m.ideal[c],m.real[c]])]],['Meses',[['Mês','Mensais','Cartão','Diários','Total geral','Sob gestão','Gastos tradicionais','Sobra'],...m.monthly.map(r=>[r.label,r.expenses,r.creditCard,r.dailyExpenses,r.general,r.managed,r.traditional,r.surplus])]],['10 maiores',[['Descrição','Valor','Mês','Origem'],...m.ranking.map(r=>[r.description,r.value,r.exportMonth,origins[r.origin]])]],['Lançamentos',[['Descrição','Valor','Mês','Origem'],...m.rows.map(r=>[r.description,r.value,r.exportMonth,origins[r.origin]])]]]};};
 p.totalHTML=function(){const {model,tables}=this.totalReportTables();return '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Total '+esc(model.label)+'</title><style>body{font:16px system-ui;margin:32px}table{border-collapse:collapse;width:100%;margin-bottom:24px}td,th{border:1px solid #ccc;padding:8px;text-align:left}</style><h1>Total '+esc(model.label)+'</h1><p>'+esc(note)+'</p>'+tables.map(([title,[head,...rows]])=>'<h2>'+esc(title)+'</h2>'+table(head,rows.map(r=>r.map(v=>typeof v==='number'?v.toLocaleString('pt-BR',{maximumFractionDigits:2}):v)))).join('')+'</html>';};
 p.exportTotalHTML=function(){const m=this.totalProjection();download(this.totalHTML(),'text/html;charset=utf-8',`total-${m.period.start}-${m.period.end}.html`);};
 const excel=p.exportarExcel,pdf=p.exportarPDF,alternate=p.exportarPDFAlternativo;
 p.exportarExcel=function(){if(this.currentMonth!=='total')return excel.apply(this,arguments);const {model,tables}=this.totalReportTables();const xml='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1"/></Style></Styles>'+tables.map(([n,r])=>this.buildExcelWorksheet(n,r)).join('')+'</Workbook>';download('\ufeff'+xml,'application/vnd.ms-excel;charset=utf-8',`total-${model.period.start}-${model.period.end}.xls`);};
 p.exportarPDF=function(){if(this.currentMonth!=='total')return pdf.apply(this,arguments);const Constructor=globalThis.jspdf?.jsPDF||globalThis.jsPDF?.jsPDF;if(!Constructor){this.showNotification('PDF indisponível. Use o relatório HTML.','error');return;}const {model,tables}=this.totalReportTables(),doc=new Constructor();doc.setFontSize(15);doc.text('Total '+model.label,14,18);let y=25;for(const [title,[head,...rows]]of tables){if(y>250){doc.addPage();y=20;}doc.setFontSize(12);doc.text(title,14,y);doc.autoTable({startY:y+4,head:[head],body:rows.map(r=>r.map(v=>typeof v==='number'?v.toLocaleString('pt-BR',{maximumFractionDigits:2}):String(v??''))),styles:{fontSize:8,overflow:'linebreak'}});y=doc.lastAutoTable.finalY+12;}doc.save(`total-${model.period.start}-${model.period.end}.pdf`);};
 p.exportarPDFAlternativo=function(){if(this.currentMonth==='total')return this.exportTotalHTML();return alternate.apply(this,arguments);};
 const render=p.renderAll;p.renderAll=function(){const result=render.apply(this,arguments);if(this.isDataLoaded&&this.currentMonth==='total')this.renderAnnualSummary();return result;};
 const deactivate=p.deactivateUser;p.deactivateUser=function(){for(const c of this.totalCharts||[])c.destroy();this.totalCharts=[];this.totalPeriod=null;return deactivate.apply(this,arguments);};
})();
